using System.Buffers.Binary;
using System.Text;
using Xunit;

public sealed class NativeTextLayoutTests
{
    private static void I32(byte[] data, int offset, int value) => BinaryPrimitives.WriteInt32LittleEndian(data.AsSpan(offset), value);
    private static void I64(byte[] data, int offset, long value) => BinaryPrimitives.WriteInt64LittleEndian(data.AsSpan(offset), value);

    // Expected offsets are literal v2 bytes, not generated by the production writer.
    private static byte[] WideFmg()
    {
        var bytes = new byte[0x64];
        I32(bytes, 0, 0x00020000); I32(bytes, 4, bytes.Length); I32(bytes, 8, 1);
        I32(bytes, 12, 1); I32(bytes, 16, 3); I32(bytes, 20, 0xff); I64(bytes, 24, 0x38);
        I32(bytes, 0x28, 0); I32(bytes, 0x2c, 1000); I32(bytes, 0x30, 1002);
        I64(bytes, 0x38, 0x50); I64(bytes, 0x40, 0); I64(bytes, 0x48, 0x58);
        Encoding.Unicode.GetBytes("One\0").CopyTo(bytes, 0x50);
        Encoding.Unicode.GetBytes("Three\0").CopyTo(bytes, 0x58);
        return bytes;
    }

    [Fact]
    public void FmgV2ReadsEveryWideOffsetWithoutInventingNullSlots()
    {
        var doc = FmgNativeDocument.Read(WideFmg());
        Assert.Equal(new string?[] { "One", null, "Three" }, doc.Entries.Select(entry => entry.Text));
        var output = doc.ApplyMutations(new[] { new FmgPatch("upsert", 1000, "Longer name") });
        Assert.Equal(0, BinaryPrimitives.ReadInt64LittleEndian(output.AsSpan(0x40)));
        var third = BinaryPrimitives.ReadInt64LittleEndian(output.AsSpan(0x48));
        Assert.Equal("Three\0", Encoding.Unicode.GetString(output, (int)third, 12));
        Assert.Equal(new string?[] { "Longer name", null, "Three" }, FmgNativeDocument.Read(output).Entries.Select(entry => entry.Text));
        var original = WideFmg();
        Assert.Equal(original, doc.Rebuild(doc.Entries.Select(entry => new FmgMutationEntry(entry.Id, entry.Text, entry.StringIndex)).ToArray()));
        var preserved = output.AsSpan(0, original.Length).ToArray();
        original.AsSpan(4, 4).CopyTo(preserved.AsSpan(4));
        original.AsSpan(0x38, 8).CopyTo(preserved.AsSpan(0x38));
        Assert.Equal(original, preserved);
    }

    [Fact]
    public void WideOffsetHighBitsAndNonUnicodeInputsFailClosed()
    {
        var bytes = WideFmg(); I64(bytes, 0x38, 0x100000050);
        Assert.ThrowsAny<Exception>(() => FmgNativeDocument.Read(bytes));
        bytes = WideFmg(); I32(bytes, 8, 0);
        Assert.Throws<NotSupportedException>(() => FmgNativeDocument.Read(bytes));
    }

    private static byte[] Binder()
    {
        var bytes = new byte[0x128]; Encoding.ASCII.GetBytes("BND4").CopyTo(bytes, 0);
        I32(bytes, 0xc, 2); I64(bytes, 0x10, 0x40); I64(bytes, 0x20, 0x24); I64(bytes, 0x28, 0x100);
        bytes[0x30] = 1; bytes[0x32] = 4; I64(bytes, 0x38, 0xe0);
        for (var i = 0; i < 2; i++) {
            var at = 0x40 + i * 0x24;
            I64(bytes, at + 8, 8); I64(bytes, at + 16, 8); I32(bytes, at + 24, 0x100 + i * 0x20);
            I32(bytes, at + 28, i); I32(bytes, at + 32, 0xa0 + i * 0x10);
            Encoding.Unicode.GetBytes($"{i}.fmg\0").CopyTo(bytes, 0xa0 + i * 0x10);
            bytes.AsSpan(0x100 + i * 0x20, 8).Fill((byte)(i + 1));
        }
        // Opaque hash/index metadata must survive payload-only relocation byte for byte.
        bytes.AsSpan(0xe0, 0x20).Fill(0xa7);
        bytes.AsSpan(0x108, 0x18).Fill(0x5b);
        return bytes;
    }

    [Fact]
    public void VariablePayloadWritePreservesBinderNameHashAndOpaqueMetadata()
    {
        var bytes = Binder(); var doc = Bnd4NativeDocument.Read(bytes);
        var entries = doc.ToRepackEntries().ToArray();
        entries[0] = entries[0] with { StoredBytes = Enumerable.Repeat((byte)9, 40).ToArray(), UncompressedSize = 40 };
        var output = doc.Repack(entries);
        Assert.Equal(bytes.AsSpan(0x88, 0x78).ToArray(), output.AsSpan(0x88, 0x78).ToArray());
        Assert.Equal(0xe0, BinaryPrimitives.ReadInt64LittleEndian(output.AsSpan(0x38)));
        var secondOffset = BinaryPrimitives.ReadUInt32LittleEndian(output.AsSpan(0x64 + 24));
        Assert.Equal(Enumerable.Repeat((byte)2, 8), output.AsSpan((int)secondOffset, 8).ToArray());
        Assert.Equal(Enumerable.Repeat((byte)0x5b, 0x18), output.AsSpan(0x108, 0x18).ToArray());
        Assert.Equal(0x120u, secondOffset);
    }

    [Fact]
    public void UnknownHashIndexCannotBeSilentlyCarriedAcrossStructuralRepack()
    {
        var doc = Bnd4NativeDocument.Read(Binder()); var entries = doc.ToRepackEntries().ToArray();
        entries[0] = entries[0] with { Name = "renamed.fmg" };
        Assert.Throws<NotSupportedException>(() => doc.Repack(entries));
    }

    [Fact]
    public void PayloadGrowthKeepsOutOfPrefixMetadataAtItsOriginalAddress()
    {
        var bytes = Binder();
        // A reader-accepted name in an inter-payload gap is not permission to
        // relocate that gap without rewriting every unknown pointer to it.
        I32(bytes, 0x64 + 32, 0x108);
        Encoding.Unicode.GetBytes("gap.fmg\0").CopyTo(bytes, 0x108);
        I64(bytes, 0x38, 0x118);
        var doc = Bnd4NativeDocument.Read(bytes);
        var entries = doc.ToRepackEntries().ToArray();
        entries[0] = entries[0] with { StoredBytes = new byte[40], UncompressedSize = 40 };
        var output = doc.Repack(entries);
        Assert.Equal("gap.fmg", Bnd4NativeDocument.Read(output).Entries[1].Name);
        Assert.Equal(bytes.AsSpan(0x108, 0x18).ToArray(), output.AsSpan(0x108, 0x18).ToArray());
        Assert.Equal(0x118, BinaryPrimitives.ReadInt64LittleEndian(output.AsSpan(0x38)));
    }

    [Fact]
    public void ReadEnvelopeDoesNotFailWhenStructuralWriterIsUnavailable()
    {
        var doc = Bnd4NativeDocument.Read(Binder());
        Assert.NotNull(doc.ToEnvelope());
        var crud = doc.VerifyCrud();
        Assert.Contains("BND4_HASH_INDEX_STRUCTURAL_REPACK_UNSUPPORTED", System.Text.Json.JsonSerializer.Serialize(crud));
    }

    [Fact]
    public void EmptyHashIndexedBinderStillHasAByteIdenticalNoOpRead()
    {
        var bytes = Binder(); I32(bytes, 0x0c, 0);
        var doc = Bnd4NativeDocument.Read(bytes);
        Assert.Equal(bytes, doc.Repack(doc.ToRepackEntries()));
        Assert.NotNull(doc.ToEnvelope());
    }
}
